def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Count how many chatting pairs are separated by a horizontal aisle at row i
    # A horizontal aisle at row i separates pairs where one student is in row < i and the other in row > i
    # Actually, the aisle is between rows, so if we place an aisle after row i (i.e., between row i and i+1),
    # it separates pairs where one is in row <= i and the other in row > i
    # But the problem says "row indices for the aisles", and the example returns '2' for M=4, K=1
    # Let's think: if we place an aisle at row index i, it means the aisle is between row i and row i+1
    # So for a pair (x1, y1, x2, y2), it is separated by a horizontal aisle at row i if:
    # (x1 <= i and x2 > i) or (x2 <= i and x1 > i)

    # Similarly for vertical aisle at column j: separates if (y1 <= j and y2 > j) or (y2 <= j and y1 > j)

    # Count for each possible horizontal aisle position (1 to M-1)
    horizontal_counts = [0] * (M - 1)  # index 0 corresponds to aisle after row 1, index 1 after row 2, etc.
    # Actually, let's use 1-indexed: aisle at position i (1 <= i <= M-1) is between row i and i+1
    # So we'll have an array of size M-1, where index i-1 corresponds to aisle after row i

    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        # For horizontal: check all possible aisle positions
        # The pair is separated by aisle at row i if (x1 <= i < x2) or (x2 <= i < x1)
        # i ranges from 1 to M-1
        if x1 < x2:
            for i in range(x1, x2):
                if 1 <= i <= M - 1:
                    horizontal_counts[i - 1] += 1
        elif x2 < x1:
            for i in range(x2, x1):
                if 1 <= i <= M - 1:
                    horizontal_counts[i - 1] += 1
        # If x1 == x2, no horizontal aisle can separate them

    # Count for each possible vertical aisle position (1 to N-1)
    vertical_counts = [0] * (N - 1)
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        if y1 < y2:
            for j in range(y1, y2):
                if 1 <= j <= N - 1:
                    vertical_counts[j - 1] += 1
        elif y2 < y1:
            for j in range(y2, y1):
                if 1 <= j <= N - 1:
                    vertical_counts[j - 1] += 1

    # Select the top K horizontal aisle positions
    # We need to select K positions from 1 to M-1 that maximize the sum of counts
    # Sort by count descending, then by position ascending for tie-breaking
    if K == 0:
        horizontal_selected = []
    else:
        # Create list of (count, position) where position is 1-indexed
        h_list = [(horizontal_counts[i], i + 1) for i in range(len(horizontal_counts))]
        # Sort by count descending, then by position ascending
        h_list.sort(key=lambda x: (-x[0], x[1]))
        horizontal_selected = [pos for count, pos in h_list[:K]]
        horizontal_selected.sort()

    # Select the top L vertical aisle positions
    if L == 0:
        vertical_selected = []
    else:
        v_list = [(vertical_counts[j], j + 1) for j in range(len(vertical_counts))]
        v_list.sort(key=lambda x: (-x[0], x[1]))
        vertical_selected = [pos for count, pos in v_list[:L]]
        vertical_selected.sort()

    # Format the output
    horizontal_str = ' '.join(map(str, horizontal_selected)) if horizontal_selected else ''
    vertical_str = ' '.join(map(str, vertical_selected)) if vertical_selected else ''

    return (horizontal_str, vertical_str)

