def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Validate inputs
    from typing import List, Tuple
    if n < 0 or m < 0:
        return 0
    if m != len(items):
        # If m doesn't match the length of items, use the actual length
        m = len(items)

    # If budget is 0 or no items, return 0
    if n == 0 or m == 0:
        return 0

    # dp[j] will store the maximum importance value achievable with budget j
    dp = [0] * (n + 1)

    for price, value in items:
        # Iterate backwards to avoid using the same item multiple times
        for j in range(n, price - 1, -1):
            if dp[j - price] + value > dp[j]:
                dp[j] = dp[j - price] + value

    return dp[n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n < 0:
        raise ValueError("Degree n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine the sign
        if terms:
            # Not the first term
            if coeff > 0:
                sign = '+'
            else:
                sign = '-'
        else:
            # First term
            if coeff < 0:
                sign = '-'
            else:
                sign = ''

        abs_coeff = abs(coeff)

        # Determine the coefficient part
        if degree == 0:
            # Constant term
            coeff_part = str(abs_coeff)
        else:
            # Term with variable
            if abs_coeff == 1:
                coeff_part = ''
            else:
                coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants by score descending, then by registration number ascending
    from typing import List, Tuple
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Calculate the cutoff index: 150% of m, rounded down
    cutoff_index = int(m * 1.5)

    # If cutoff_index is 0, no one qualifies? But let's handle edge cases
    if cutoff_index == 0:
        return (0, [])

    # The cutoff score is the score of the applicant at position cutoff_index - 1 (0-indexed)
    # But we need to include all applicants with score >= cutoff_score
    if cutoff_index > len(sorted_applicants):
        cutoff_index = len(sorted_applicants)

    if cutoff_index == 0:
        return (0, [])

    cutoff_score = sorted_applicants[cutoff_index - 1][1]

    # Collect all applicants with score >= cutoff_score
    qualified = [applicant for applicant in sorted_applicants if applicant[1] >= cutoff_score]

    return (cutoff_score, qualified)

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")

    # Check for factor 2
    if n % 2 == 0:
        return n // 2

    # Check odd factors starting from 3
    i = 3
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 2

    # If no factors found, n is prime
    return n

